export const dimensions=['Technical accuracy','Commercial control','Customer outcome','Efficiency','Evidence quality'];
export const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
export function validateScenario(s){
 const fail=m=>{throw Error(m)};const str=(v,n)=>{if(typeof v!=='string'||!v.trim())fail(n+' must be text')};
 if(!s||s.schemaVersion!==1)fail('Use scenario schemaVersion 1.');str(s.id,'id');str(s.title,'title');str(s.claimant,'claimant');str(s.claimRef,'claimRef');str(s.vehicle,'vehicle');
 if(!Number.isFinite(s.dailyRate)||s.dailyRate<=0||s.dailyRate>10000)fail('Daily rate must be between 0 and 10,000.');
 if(!Array.isArray(s.stages)||s.stages.length<2||s.stages.length>30)fail('Use 2–30 stages.');
 if(!Array.isArray(s.artifacts))fail('artifacts must be a list.');const ids=new Set();
 s.artifacts.forEach(a=>{str(a.id,'Artifact id');if(ids.has(a.id))fail('Duplicate artifact id');ids.add(a.id);['title','kind','from','body'].forEach(k=>str(a[k],k));if(!Number.isInteger(a.unlock)||a.unlock<0||a.unlock>=s.stages.length)fail('Invalid artifact unlock stage');if(a.variants&&!Array.isArray(a.variants))fail('Invalid artifact variants');(a.variants||[]).forEach(v=>{str(v.flag,'variant flag');str(v.body,'variant body')})});
 const stageIds=new Set();s.stages.forEach(t=>{str(t.id,'Stage id');if(stageIds.has(t.id))fail('Duplicate stage id');stageIds.add(t.id);['title','prompt','phase'].forEach(k=>str(t[k],k));if(!['choice','multi','allocation','note'].includes(t.type))fail('Unsupported stage type');if(!Number.isFinite(t.xp)||t.xp<0)fail('Invalid XP');if(!Number.isInteger(t.days)||t.days<0)fail('Invalid stage days');if(!Array.isArray(t.docs)||t.docs.some(id=>!ids.has(id)))fail('Unknown stage document');
 if(t.type==='choice'||t.type==='multi'){if(!Array.isArray(t.options)||t.options.length<2)fail('Each decision needs options');const oi=new Set();t.options.forEach(o=>{str(o.id,'Option id');str(o.label,'Option label');if(oi.has(o.id))fail('Duplicate option');oi.add(o.id);if(t.type==='choice'){if(!Array.isArray(o.score)||o.score.length!==5||o.score.some(n=>!Number.isFinite(n)||Math.abs(n)>50))fail('Five score changes required');if(!Number.isFinite(o.quality)||o.quality<0||o.quality>1)fail('Quality must be 0–1');if(o.extraDays!==undefined&&(!Number.isInteger(o.extraDays)||o.extraDays<0||o.extraDays>30))fail('Invalid delay');str(o.feedback,'Feedback');if(o.flags&&(!Array.isArray(o.flags)||o.flags.some(f=>typeof f!=='string')))fail('Flags must be text')}});if(t.type==='multi'&&(!Array.isArray(t.correct)||!t.correct.length||t.correct.some(id=>!oi.has(id))))fail('Invalid correct choices');}
 if(t.type==='allocation'){if(!Array.isArray(t.issues)||!t.issues.length)fail('Allocation issues required');t.issues.forEach(i=>{str(i.id,'Issue id');str(i.label,'Issue label');if(!['Accept','Challenge','Investigate'].includes(i.answer))fail('Invalid allocation answer')})}
 if(t.type==='note'){if(!Array.isArray(t.rubric)||!t.rubric.length)fail('Note rubric required');t.rubric.forEach(r=>{str(r.id,'Rubric id');str(r.label,'Rubric label');if(!Array.isArray(r.terms)||r.terms.some(x=>typeof x!=='string'))fail('Rubric terms required')})}
 });if(s.stages.at(-1).type!=='note')fail('The final stage must be a strategy note.');str(s.modelNote,'Model strategy');if(s.sources&&(!Array.isArray(s.sources)||s.sources.some(x=>typeof x.title!=='string'||typeof x.url!=='string')))fail('Invalid source links');if(s.coaching&&(!Array.isArray(s.coaching)||s.coaching.some(x=>typeof x!=='string')))fail('Invalid coaching prompts');return s;
}
export const initialState=s=>({scenarioId:s.id,index:0,day:1,scores:[50,50,50,50,50],xp:0,flags:[],history:[],read:[],note:'',complete:false});
export function artifactBody(a,state){const v=(a.variants||[]).find(v=>state.flags.includes(v.flag));return (v?.body||a.body).replaceAll('{{day}}',String(state.day)).replaceAll('{{hire}}',money(state.day*state.rate)).replaceAll('{{total}}',money(state.day*state.rate+390));}
export function evaluate(s,state,answer){
 if(state.complete||state.index>=s.stages.length)throw Error('The claim is complete.');const t=s.stages[state.index];let quality=0,score=[0,0,0,0,0],extraDays=0,flags=[],feedback='',label='',coverage=[];
 if(t.type==='choice'){const o=t.options.find(o=>o.id===answer);if(!o)throw Error('Choose an action first.');({quality,score,feedback}=o);extraDays=o.extraDays||0;flags=o.flags||[];label=o.label;}
 if(t.type==='multi'){if(!Array.isArray(answer)||!answer.length||answer.some(id=>!t.options.some(o=>o.id===id)))throw Error('Select at least one evidence item.');const a=[...new Set(answer)];quality=Math.max(0,(a.filter(id=>t.correct.includes(id)).length-a.filter(id=>!t.correct.includes(id)).length)/t.correct.length);score=[Math.round(10*quality),Math.round(5*quality),Math.round(3*quality),Math.round(6*quality),Math.round(15*quality)];if(quality<.5){score[0]=-8;score[4]=-10;extraDays=t.missDelay||0;}if(quality===1&&t.flag)flags=[t.flag];feedback=t.feedback;label=a.map(id=>t.options.find(o=>o.id===id).label).join('; ');}
 if(t.type==='allocation'){if(!answer||t.issues.some(i=>!['Accept','Challenge','Investigate'].includes(answer[i.id])))throw Error('Allocate every issue before continuing.');quality=t.issues.filter(i=>answer[i.id]===i.answer).length/t.issues.length;score=[Math.round(15*quality),Math.round(10*quality),Math.round(5*quality),Math.round(5*quality),Math.round(10*quality)];feedback=t.feedback;label=t.issues.map(i=>i.label+': '+answer[i.id]).join('; ');if(quality>=.75)flags=['strategy'];}
 if(t.type==='note'){if(typeof answer!=='string')throw Error('Write your strategy note.');const count=answer.trim().split(/\s+/).filter(Boolean).length;if(count<30||count>150)throw Error('Use 30–150 words for your strategy note.');const text=answer.toLowerCase();coverage=t.rubric.filter(r=>r.terms.some(term=>text.includes(term.toLowerCase()))).map(r=>r.id);quality=coverage.length/t.rubric.length;score=[Math.round(8*quality),Math.round(5*quality),Math.round(5*quality),Math.round(5*quality),Math.round(15*quality)];feedback='Your note was checked for topic coverage only. This is not an assessment of legal correctness or reasoning; compare it with the model strategy and discuss it with your coach.';label=answer;if(quality===1)flags=['rationale'];}
 return {stageId:t.id,title:t.title,type:t.type,answer,label,quality,score,extraDays,days:t.days+extraDays,flags,feedback,coverage,xp:Math.round(t.xp*quality),dayBefore:state.day,dayAfter:state.day+t.days+extraDays};
}
export function commit(s,state,answer){const r=evaluate(s,state,answer);return {...state,index:state.index+1,day:r.dayAfter,scores:state.scores.map((n,i)=>Math.max(0,Math.min(100,n+r.score[i]))),xp:state.xp+r.xp,flags:[...new Set([...state.flags,...r.flags])],history:[...state.history,r],note:r.type==='note'?answer:state.note,complete:state.index+1===s.stages.length};}
export function badges(state){const f=state.flags;return [{name:'Hire Detective',earned:['need','type','repairs'].every(x=>f.includes(x)),why:'Investigate need, vehicle type and repair evidence.'},{name:'Meter Stopper',earned:f.includes('intervention')&&f.includes('chased'),why:'Make a suitable offer and act on repair delay.'},{name:'Rate Analyst',earned:f.includes('rates'),why:'Identify both useful comparable rate reports.'},{name:'Evidence Controller',earned:f.includes('finance'),why:'Request proportionate financial evidence.'},{name:'Credit Hire Strategist',earned:state.complete&&state.scores.every(n=>n>=75)&&f.includes('strategy'),why:'Finish with at least 75 in every dimension and a sound issue allocation.'}];}
export function outcome(state){if(state.scores[2]<45)return {title:'Rebuild trust, then resolve',body:'Your approach has put the customer relationship under strain. A senior handler takes over to explain the mobility position, correct unsupported assumptions and agree proportionate next steps.'};if(state.scores.every(n=>n>=65)&&state.flags.includes('strategy'))return {title:'A defensible negotiation',body:'Your file supports a reasoned negotiation. Need and appropriate mobility are recognised; period, rates and additional charges can be discussed with evidence. No fixed settlement figure is treated as the right answer.'};return {title:'Evidence gap: refer and recover',body:'The claim is still resolvable, but missing evidence or avoidable delay weakens the current position. A technical referral and a specific evidence plan are needed before making a firm settlement recommendation.'};}
